## 3. Section JSON Schema

Each template version stores `sections: ConsentSection[]` in JSONB. Full typed schema:

```typescript
// types/consent.ts

type SectionKind =
  | 'heading'
  | 'paragraph'
  | 'signature'
  | 'checkbox'
  | 'text_input'
  | 'date'
  | 'dropdown'
  | 'file_upload'
  | 'initials'
  | 'ink_disclosure'
  | 'reach_batch_record';

interface BaseSection {
  id: string;          // nanoid(10) — stable across edits
  kind: SectionKind;
  label: string;       // shown above section to signer
  required: boolean;
  order: number;       // integer, 0-indexed, contiguous
}

interface HeadingSection extends BaseSection {
  kind: 'heading';
  level: 1 | 2 | 3;   // maps to text-2xl / text-xl / text-lg
}

interface ParagraphSection extends BaseSection {
  kind: 'paragraph';
  body: string;        // markdown, rendered via react-markdown
}

interface SignatureSection extends BaseSection {
  kind: 'signature';
  signer: 'client' | 'guardian';  // guardian = second pad
}

interface CheckboxSection extends BaseSection {
  kind: 'checkbox';
  body: string;        // markdown text of the checkbox statement
}

interface TextInputSection extends BaseSection {
  kind: 'text_input';
  placeholder?: string;
  min_length?: number;
  max_length?: number;
  regex?: string;      // stored as string, validated on submit
  regex_error?: string;
}

interface DateSection extends BaseSection {
  kind: 'date';
  min_age?: number;    // e.g. 18 — shows warning if DOB is under this age
}

interface DropdownSection extends BaseSection {
  kind: 'dropdown';
  options: { value: string; label: string }[];
}

interface FileUploadSection extends BaseSection {
  kind: 'file_upload';
  accept: string[];    // e.g. ['image/jpeg','image/png','application/pdf']
  max_size_mb: number; // default 5
}

interface InitialsSection extends BaseSection {
  kind: 'initials';
  body: string;        // markdown — text to initial
}

interface InkDisclosureSection extends BaseSection {
  kind: 'ink_disclosure';
  // Body is auto-generated from EU REACH regulations text.
  // `ink_names` is populated by artist post-session. Client sees disclosure text only.
  disclosure_text: string;  // markdown, REACH-compliant, editable in template
}

interface ReachBatchRecordSection extends BaseSection {
  kind: 'reach_batch_record';
  // Artist fills batch numbers post-session from the submission detail page.
  // Client sees placeholder text on signing page.
  artist_instructions: string;  // shown in authed submission view for artist
}

type ConsentSection =
  | HeadingSection
  | ParagraphSection
  | SignatureSection
  | CheckboxSection
  | TextInputSection
  | DateSection
  | DropdownSection
  | FileUploadSection
  | InitialsSection
  | InkDisclosureSection
  | ReachBatchRecordSection;
```

