const STATUS_MAP = {
  signed:  { dot: 'consent-dot-signed',  label: 'Signed',  badge: 'badge-consent-signed' },
  pending: { dot: 'consent-dot-pending', label: 'Pending', badge: 'badge-consent-pending' },
  expired: { dot: 'consent-dot-expired', label: 'Expired', badge: 'badge-consent-expired' },
  deleted: { dot: 'consent-dot-deleted', label: 'Deleted', badge: 'badge-consent-deleted' },
  opened:  { dot: 'consent-dot-opened',  label: 'Opened',  badge: 'badge-consent-opened' },
} as const;

export function ConsentStatusDot({ status }: { status: keyof typeof STATUS_MAP }) {
  const { dot, label, badge } = STATUS_MAP[status];
  return (
    <div className="flex items-center gap-2">
      <span className={cn('inline-block h-2 w-2 rounded-full', dot)} />
      <span className={cn('text-xs px-1.5 py-0.5 rounded font-medium', badge)}>
        {label}
      </span>
    </div>
  );
}
