**localStorage recovery:**

```typescript
// On mount of the signing page
const STORAGE_KEY = `inkos:consent:${token}:progress`;

useEffect(() => {
  const saved = localStorage.getItem(STORAGE_KEY);
  if (!saved) return;
  const parsed = JSON.parse(saved) as ConsentProgress;
  // Restore answers to state if token matches (already confirmed by page params)
  setAnswers(parsed.answers);
  setCompletedSections(new Set(parsed.completedSections));
  // Show toast: "Your progress was restored"
  toast.info('Progress restored', { description: 'We saved your answers from your last visit.' });
}, [token]);

// On each section completion, write to localStorage
function markSectionComplete(sectionId: string, answer: unknown) {
  setAnswers(prev => {
    const next = { ...prev, [sectionId]: answer };
    const progress: ConsentProgress = {
      answers: next,
      completedSections: [...completedSections, sectionId],
      savedAt: new Date().toISOString(),
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(progress));
    return next;
  });
}

// On successful submit, clear localStorage
function onSubmitSuccess() {
  localStorage.removeItem(STORAGE_KEY);
}
```

