## 5. Signature Pad Component Spec

**File:** `components/consent/SignaturePad.tsx`

```tsx
'use client';

import SignatureCanvas from 'react-signature-canvas';
import { useRef, useState, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

interface SignaturePadProps {
  onCapture: (png: string, svg: string) => void;
  onClear: () => void;
  disabled?: boolean;
  height?: number;       // default 180
  label?: string;
  required?: boolean;
  hasValue?: boolean;
}

export function SignaturePad({
  onCapture,
  onClear,
  disabled = false,
  height = 180,
  label,
  required = false,
  hasValue = false,
}: SignaturePadProps) {
  const sigRef = useRef<SignatureCanvas>(null);
  const [strokeCount, setStrokeCount] = useState(0);

  const MIN_STROKES = 3;
  const MIN_POINTS = 20;
  const isValid = strokeCount >= MIN_STROKES;

  const handleEnd = useCallback(() => {
    if (!sigRef.current) return;
    const data = sigRef.current.toData();
    const totalPoints = data.reduce((acc, stroke) => acc + stroke.length, 0);
    const strokes = data.length;
    setStrokeCount(strokes);

    if (strokes >= MIN_STROKES && totalPoints >= MIN_POINTS) {
      const png = sigRef.current.getTrimmedCanvas().toDataURL('image/png');
      // Build SVG from point data
      const svg = buildSvgFromPoints(data, sigRef.current.getTrimmedCanvas().width, sigRef.current.getTrimmedCanvas().height);
      onCapture(png, svg);
    }
  }, [onCapture]);

  const handleClear = useCallback(() => {
    sigRef.current?.clear();
    setStrokeCount(0);
    onClear();
  }, [onClear]);

  return (
    <div className="space-y-2">
      {label && (
        <label className="text-sm font-medium">
          {label}
          {required && <span className="text-destructive ml-1">*</span>}
        </label>
      )}
      <div className={cn('sig-pad-wrapper overflow-hidden', hasValue && 'sig-has-value')}>
        <SignatureCanvas
          ref={sigRef}
          penColor="oklch(97% 0.01 264)"
          backgroundColor="oklch(6% 0.01 264)"
          canvasProps={{
            height,
            style: { width: '100%', touchAction: 'none' },
            'aria-label': label ?? 'Signature pad',
          }}
          onEnd={handleEnd}
          dotSize={2}
          minWidth={1.5}
          maxWidth={3}
          velocityFilterWeight={0.7}
        />
      </div>
      <div className="flex items-center justify-between">
        <p className="text-xs text-muted-foreground">
          {hasValue
            ? 'Signature captured'
            : disabled
            ? 'Signature locked'
            : 'Draw your signature above'}
        </p>
        {!disabled && (
          <Button variant="ghost" size="sm" onClick={handleClear} className="h-7 text-xs">
            Clear
          </Button>
        )}
      </div>
    </div>
  );
}

// SVG path builder from react-signature-canvas point data
function buildSvgFromPoints(
  data: { x: number; y: number; time: number }[][],
  width: number,
  height: number
): string {
  const paths = data.map(stroke => {
    if (stroke.length === 0) return '';
    const d = stroke.reduce((acc, pt, i) =>
      i === 0 ? `M ${pt.x} ${pt.y}` : `${acc} L ${pt.x} ${pt.y}`, '');
    return `<path d="${d}" stroke="white" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`;
  }).join('\n');

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" style="background:black">\n${paths}\n</svg>`;
}
```

**Touch + mouse + stylus:** Handled by `react-signature-canvas` natively via pointer events. `touchAction: 'none'` on the canvas prevents page scroll while drawing.

**Keyboard accessibility:** The canvas itself is not keyboard-navigable (by nature). Provide a text-based fallback for typed initials where appropriate (`initials` section type includes a text input as an alternative).

**Mobile auto-fit:** The canvas uses `style={{ width: '100%' }}`. The pixel dimensions are managed internally by `react-signature-canvas` which listens to window resize and scales the canvas element. On mobile, this means the pad fills the full card width automatically.

**Validation gate:** `isValid` is true only when `strokeCount >= 3 AND totalPoints >= 20`. The "Sign and submit" CTA remains disabled until all required signature pads pass this check.

