```typescript
interface ConsentFormRendererProps {
  sections: ConsentSection[];
  mode: 'preview' | 'signing' | 'readonly';
  answers?: Record<string, unknown>;          // readonly mode
  onAnswer?: (sectionId: string, value: unknown) => void;  // signing mode
